-- Optional fixture for outbound OBJECT_GRANT exports.
-- Define ORACODE_GRANTEE to an existing user or role before running.
-- Example:
--   DEFINE ORACODE_GRANTEE = ORACODE_READONLY
--   @tests/fixtures/oracle/optional_grants.sql

SET VERIFY OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE

GRANT SELECT ON OC_DEPARTMENTS TO &&ORACODE_GRANTEE;
GRANT SELECT ON OC_EMPLOYEES TO &&ORACODE_GRANTEE;
GRANT SELECT ON OC_EMPLOYEE_V TO &&ORACODE_GRANTEE;
GRANT EXECUTE ON OC_REPORTING_PKG TO &&ORACODE_GRANTEE;

PROMPT Optional object grants fixture loaded for &&ORACODE_GRANTEE
UNDEFINE ORACODE_GRANTEE
